const loginForm =
  document.getElementById('loginForm');


loginForm.addEventListener(
  'submit',
  async (e) => {

    e.preventDefault();


    const email =
      document.getElementById(
        'loginEmail'
      ).value;


    const password =
      document.getElementById(
        'loginPassword'
      ).value;


    const message =
      document.getElementById(
        'loginMessage'
      );


    const { error } =
      await supabaseClient.auth
        .signInWithPassword({

          email: email,

          password: password

        });


    if (error) {

      message.textContent =
        error.message;

      return;
    }


    await checkAccess();


    document.getElementById(
      'authScreen'
    ).style.display = 'none';

  }
);


/* =========================================================
   CREARE CONT
   ========================================================= */

const showSignupBtn =
  document.getElementById(
    'showSignupBtn'
  );


const signupForm =
  document.getElementById(
    'signupForm'
  );


showSignupBtn.addEventListener(
  'click',
  () => {

    loginForm.style.display =
      'none';

    showSignupBtn.style.display =
      'none';

    signupForm.style.display =
      'flex';

  }
);


signupForm.addEventListener(
  'submit',
  async (e) => {

    e.preventDefault();


    const email =
      document.getElementById(
        'signupEmail'
      ).value;


    const password =
      document.getElementById(
        'signupPassword'
      ).value;


    const passwordConfirm =
      document.getElementById(
        'signupPasswordConfirm'
      ).value;


    const message =
      document.getElementById(
        'signupMessage'
      );


    if (
      password !== passwordConfirm
    ) {

      message.textContent =
        'Parolele nu coincid.';

      return;
    }


    const { error } =
      await supabaseClient.auth
        .signUp({

          email: email,

          password: password

        });


    if (error) {

      message.textContent =
        error.message;

      return;
    }


    message.textContent =
      'Contul a fost creat. Se deschide site-ul...';


    await checkAccess();


    document.getElementById(
      'authScreen'
    ).style.display = 'none';

  }
);


/* =========================================================
   VERIFICARE ACCES
   ========================================================= */

async function checkAccess() {

  const {
    data: { session }
  } =
    await supabaseClient.auth
      .getSession();


  if (!session) {

    document.getElementById(
      'authScreen'
    ).style.display = 'flex';

    return;
  }


  const { data: access } =
    await supabaseClient
      .from('access_requests')
      .select('approved')
      .eq('id', session.user.id)
      .single();


  accessApproved =
    !!access?.approved;


  document.getElementById(
    'authScreen'
  ).style.display = 'none';
}


checkAccess();


